"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6388],{63025:e=>{e.exports=JSON.parse('{"functions":[{"name":"ListenForKey","desc":"Returns a signal that fires whenever `keyCode` is pressed or `button` is\\nactivated. Both arguments are optional; supply either or both.\\n\\nThe key binding listens on [UserInputService.InputBegan] without checking\\n`gameProcessedEvent`, so the shortcut still fires while the player is typing in a\\nTextBox.\\n\\nDestroying the returned signal disconnects both listeners \u2014 do that when the UI\\ncloses, or the connections leak.\\n\\n```lua\\nlocal pressed = ListenForKey(Enum.KeyCode.E, promptButton)\\n\\npressed:Connect(function()\\n\\topenShop()\\nend)\\n\\n-- later\\npressed:Destroy()\\n```","params":[{"name":"keyCode","desc":"Keyboard shortcut to listen for","lua_type":"Enum.KeyCode?"},{"name":"button","desc":"Button whose `Activated` also fires the signal","lua_type":"TextButton | ImageButton?"}],"returns":[{"desc":"","lua_type":"Signal.Signal<nil>"}],"function_type":"static","realm":["Client"],"source":{"line":46,"path":"src/Shared/Modules/ListenForKey.luau"}}],"properties":[],"types":[],"name":"ListenForKey","desc":"Bundles a keyboard shortcut and an on-screen button behind a single [Signal], so\\nUI code does not have to wire up (and tear down) both input paths itself.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":10,"path":"src/Shared/Modules/ListenForKey.luau"}}')}}]);